## Display Map (PC, rclgd). Datos → textura sin bucles; paleta 256×1 en shader (como RViz).
const Paletas := preload("res://comun/viz/paletas.gd")   # makeMapPalette/Costmap/Raw portadas (fichas 2 y 3)
const SH := "shader_type spatial; render_mode unshaded, cull_disabled;
uniform sampler2D datos : filter_nearest; uniform sampler2D paleta : filter_nearest; uniform float alfa = 1.0;
void fragment() { int i = int(texture(datos, UV).r * 255.0 + 0.5);
vec4 c = texelFetch(paleta, ivec2(i, 0), 0); ALBEDO = c.rgb; ALPHA = c.a * alfa; }"
@export var topic := "/map"
@export_enum("map", "costmap", "raw") var esquema := 0
@export_range(0.0, 1.0) var alfa := 0.7
var ctx                       # contexto_ros.gd de las plantillas (nodo + qos)
var img: Image; var tex: ImageTexture; var _sub: RosSubscriber
var _mat := ShaderMaterial.new()

func _ready() -> void:
	_mat.shader = Shader.new(); _mat.shader.code = SH
	_mat.set_shader_parameter("paleta", ImageTexture.create_from_image(Paletas.imagen(esquema)))
	_mat.set_shader_parameter("alfa", alfa)
	material_override = _mat
	_sub = ctx.nodo.create_subscription(topic, "nav_msgs/msg/OccupancyGrid", _on_mapa, ctx.qos(false, 1, true))

func _on_mapa(m) -> void:
	var w: int = m.info.width; var h: int = m.info.height
	img = Image.create_from_data(w, h, false, Image.FORMAT_RGBA8, m.data.to_byte_array())
	tex = ImageTexture.create_from_image(img)
	_mat.set_shader_parameter("datos", tex)
	var o = m.info.origin
	transform = Transform3D(Basis(rclgd.ros_to_godot_quat(Quaternion(o.orientation.x, o.orientation.y,
		o.orientation.z, o.orientation.w))), rclgd.ros_to_godot_vector(Vector3(o.position.x, o.position.y, o.position.z)))
	var lx: float = w * m.info.resolution; var ly: float = h * m.info.resolution
	var v := PackedVector3Array(); var uv := PackedVector2Array()
	for p in [Vector2(0, 0), Vector2(1, 0), Vector2(1, 1), Vector2(0, 0), Vector2(1, 1), Vector2(0, 1)]:
		v.append(rclgd.ros_to_godot_vector(Vector3(p.x * lx, p.y * ly, 0.0))); uv.append(p)
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = v; arr[Mesh.ARRAY_TEX_UV] = uv
	var am := ArrayMesh.new()
	am.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	mesh = am

