## paletas.gd (parte costmap). Port literal de makeCostmapPalette (palette_builder.cpp:110-134).
static func _base() -> PackedByteArray:
	var p := PackedByteArray()
	p.resize(1024)
	for i in range(101, 128):              # ilegales positivos: verde
		p[4 * i + 1] = 255; p[4 * i + 3] = 255
	for i in range(128, 255):              # ilegales negativos: rojo → amarillo
		p[4 * i] = 255; p[4 * i + 1] = 255 * (i - 128) / (254 - 128); p[4 * i + 3] = 255
	p[1020] = 0x70; p[1021] = 0x89; p[1022] = 0x86; p[1023] = 255   # 255 = −1 desconocido
	return p

static func costmap(binaria := false, umbral := 100) -> Image:
	var p := _base()
	for i in 101:
		var c := Color8(0, 0, 0, 255)
		if binaria:
			c = Color8(0, 0, 255) if i < umbral else Color8(255, 0, 0)
		elif i == 0:
			c = Color8(0, 0, 0, 0)               # libre: transparente
		elif i <= 98:
			var v := 255 * i / 100
			c = Color8(v, 0, 255 - v)
		elif i == 99:
			c = Color8(0, 255, 255)              # inscrito: cian
		else:
			c = Color8(255, 0, 255)              # letal: magenta
		p[4 * i] = c.r8; p[4 * i + 1] = c.g8; p[4 * i + 2] = c.b8; p[4 * i + 3] = c.a8
	return Image.create_from_data(256, 1, false, Image.FORMAT_RGBA8, p)

## Vita: LUT de 16 niveles del formato propuesto /vita/costmap_tesela (4 bit), sacada de la misma paleta.
static func lut16() -> PackedColorArray:
	var img := costmap()
	var idx := [255, 0, 8, 16, 24, 32, 40, 48, 56, 64, 72, 80, 88, 98, 99, 100]
	var out := PackedColorArray()
	for i in idx:
		out.append(img.get_pixel(i, 0))
	return out

## paletas.gd (parte raw + selector). makeRawPalette (palette_builder.cpp:136-152) y makeMapPalette (:87-108).
static func raw(binaria := false, umbral := 100) -> Image:
	var p := PackedByteArray()
	p.resize(1024)
	for i in 256:
		var v := i
		if binaria:
			v = 0 if i < umbral else 255
		p[4 * i] = v; p[4 * i + 1] = v; p[4 * i + 2] = v; p[4 * i + 3] = 255
	return Image.create_from_data(256, 1, false, Image.FORMAT_RGBA8, p)

static func mapa(binaria := false, umbral := 65) -> Image:
	var p := _base()   # ilegales y −1 (ficha costmap)
	for i in 101:
		var v := 255 - 255 * i / 100
		if binaria:
			v = 255 if i < umbral else 0
		p[4 * i] = v; p[4 * i + 1] = v; p[4 * i + 2] = v; p[4 * i + 3] = 255
	return Image.create_from_data(256, 1, false, Image.FORMAT_RGBA8, p)

static func imagen(esquema: int, binaria := false, umbral := 65) -> Image:
	match esquema:
		1: return costmap(binaria, umbral)
		2: return raw(binaria, umbral)
	return mapa(binaria, umbral)

## Añadido al display Map (ficha 1): aplicar map_msgs/OccupancyGridUpdate (map_display.cpp:353-410).
@export var hz_subida := 10.0
var _sub_upd: RosSubscriber
var _sucio := false
var _t_subida := 0

func suscribir_updates(topic_upd: String) -> void:
	var q: RosQoS = ctx.qos(false, 5)                  # RViz: rclcpp::QoS(5) fiable
	_sub_upd = ctx.nodo.create_subscription(topic_upd, "map_msgs/msg/OccupancyGridUpdate", _on_update, q)

func _on_update(u) -> void:
	if img == null:
		return                                        # RViz también ignora updates sin mapa
	var x: int = u.x
	var y: int = u.y
	var w: int = u.width
	var h: int = u.height
	if x < 0 or y < 0 or x + w > img.get_width() or y + h > img.get_height() or w * h == 0:
		push_warning("OccupancyGridUpdate fuera del mapa")
		return
	var parche := Image.create_from_data(w, h, false, Image.FORMAT_RGBA8, u.data.to_byte_array())
	img.blit_rect(parche, Rect2i(0, 0, w, h), Vector2i(x, y))
	_sucio = true

func _process(_dt: float) -> void:
	var ahora := Time.get_ticks_msec()
	if _sucio and ahora - _t_subida >= int(1000.0 / hz_subida):
		tex.update(img)                                 # mismo tamaño y formato: no recrea la textura
		_sucio = false
		_t_subida = ahora

