## GridCells (PC): una instancia por celda, sin color por instancia (todas iguales, como RViz).
@export var color := Color(0.0, 0.6, 1.0, 0.5)
@export var max_celdas := 20000
var ctx
var _sub: RosSubscriber

func _ready() -> void:
	multimesh = MultiMesh.new()
	multimesh.transform_format = MultiMesh.TRANSFORM_3D
	var caja := BoxMesh.new()
	caja.size = Vector3(1.0, 0.01, 1.0)
	var mat := StandardMaterial3D.new()
	mat.albedo_color = color
	mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA if color.a < 1.0 else BaseMaterial3D.TRANSPARENCY_DISABLED
	mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	caja.material = mat
	multimesh.mesh = caja

func suscribir(topic: String) -> void:
	_sub = ctx.nodo.create_subscription(topic, "nav_msgs/msg/GridCells", _on_celdas, ctx.qos(false, 1))

func _on_celdas(m) -> void:
	var celdas: Array = m.cells
	var n := mini(celdas.size(), max_celdas)
	multimesh.instance_count = n
	var b := Basis.from_scale(Vector3(m.cell_height, 1.0, m.cell_width))   # ROS y → Godot X, ROS x → Godot Z
	for i in n:
		var p = celdas[i]
		multimesh.set_instance_transform(i, Transform3D(b, rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z))))

