## VoxelGrid de Nav2 (PC). Solo vóxeles MARCADOS (bit 16+z), como pub_marked de costmap_2d_cloud.cpp.
@export var max_voxeles := 30000
var ctx
var _sub: RosSubscriber

func suscribir(topic: String) -> void:
	multimesh = MultiMesh.new()
	multimesh.transform_format = MultiMesh.TRANSFORM_3D
	multimesh.mesh = BoxMesh.new()
	_sub = ctx.nodo.create_subscription(topic, "nav2_msgs/msg/VoxelGrid", _on_grid, ctx.qos(false, 1))

func _on_grid(g) -> void:
	var d = g.data
	var sx: int = g.size_x
	var sy: int = g.size_y
	var sz: int = mini(g.size_z, 16)
	var r := Vector3(g.resolutions.x, g.resolutions.y, g.resolutions.z)
	var o := Vector3(g.origin.x, g.origin.y, g.origin.z)
	var pos := PackedVector3Array()
	for k in sx * sy:
		var marcados: int = (int(d[k]) >> 16) & 0xFFFF
		if marcados == 0:
			continue
		for z in sz:
			if (marcados >> z) & 1 and pos.size() < max_voxeles:
				pos.append(o + Vector3((k % sx) + 0.5, (k / sx) + 0.5, z + 0.5) * r)
	multimesh.instance_count = pos.size()
	var b := Basis.from_scale(Vector3(r.y, r.z, r.x))    # escala ROS → ejes locales Godot
	for i in pos.size():
		multimesh.set_instance_transform(i, Transform3D(b, rclgd.ros_to_godot_vector(pos[i])))

