## GridMap (PC): superficie de alturas de `capa`, coloreada con rampa. Column-major + búfer circular.
@export var capa := "elevation"
@export var rango := Vector2(-0.5, 1.0)
var ctx
var _sub: RosSubscriber

func _on_grid(g) -> void:
	var k: int = Array(g.layers).find(capa)
	if k < 0:
		return
	var res: float = g.info.resolution
	var filas := int(round(g.info.length_x / res))
	var cols := int(round(g.info.length_y / res))
	var z: PackedFloat32Array = g.data[k].data
	var s0: int = g.outer_start_index
	var s1: int = g.inner_start_index
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for i in filas - 1:
		for j in cols - 1:
			var q := [Vector2i(i, j), Vector2i(i + 1, j), Vector2i(i + 1, j + 1), Vector2i(i, j + 1)]
			var v := []
			for c in q:
				var h := z[((c.x + s0) % filas) + ((c.y + s1) % cols) * filas]
				var p := Vector3(g.info.length_x / 2 - (c.x + 0.5) * res, g.info.length_y / 2 - (c.y + 0.5) * res, h)
				v.append([rclgd.ros_to_godot_vector(p), Color.from_hsv(0.66 * (1.0 - inverse_lerp(rango.x, rango.y, h)), 1, 1)])
			if v.any(func(e): return is_nan(e[0].y)):
				continue
			for t in [0, 1, 2, 0, 2, 3]:
				st.set_color(v[t][1]); st.add_vertex(v[t][0])
	mesh = st.commit()
	var o = g.info.pose
	transform = Transform3D(Basis(rclgd.ros_to_godot_quat(Quaternion(o.orientation.x, o.orientation.y, o.orientation.z,
		o.orientation.w))), rclgd.ros_to_godot_vector(Vector3(o.position.x, o.position.y, o.position.z)))

