## Gestor (marker_common.cpp:205-310, marker_base.cpp:84-115). _process: caducidad (4 Hz) y frame_locked.
const Fab := preload("res://comun/viz/fabrica.gd")   # propuesta: borrador §3
@export var fixed_frame := "map"
@export var max_marcadores := 48                  # Vita: ADR 0011
var tf: RosTfListener                             # null en la Vita
var _ns := {}                                     # ns → {id → {n, tipo, expira, frame, pose, locked}}
var _pool := {}; var _total := 0                  # _pool: tipo → Array de nodos ocultos
func on_marker(m) -> void:
	match m.action:
		0: _add(m)
		2: _borrar(m.ns, m.id)
		3:
			for ns in ([m.ns] if m.ns != "" else _ns.keys()):
				for id in _ns.get(ns, {}).keys():
					_borrar(ns, id)

func _add(m) -> void:
	var tabla: Dictionary = _ns.get_or_add(m.ns, {})
	var e = tabla.get(m.id)
	if e != null and e.tipo != m.type:
		_borrar(m.ns, m.id); e = null
	if e == null:
		if _total >= max_marcadores: return
		var libres: Array = _pool.get_or_add(m.type, [])
		e = {"n": libres.pop_back() if libres else Fab.crear(m.type), "tipo": m.type}
		if e.n.get_parent() == null: add_child(e.n)
		tabla[m.id] = e; _total += 1
	var vida: float = m.lifetime.sec + m.lifetime.nanosec * 1e-9
	e.expira = Time.get_ticks_msec() + int(vida * 1000.0) if vida > 1e-4 else -1
	e.frame = m.header.frame_id; e.locked = m.frame_locked; e.pose = Fab.pose(m.pose)
	e.n.transform = _marco(e.frame, m.header.stamp) * e.pose
	e.n.visible = Fab.aplicar(e.n, m)                # después: fija malla, color y n.scale; false si escala 0
func _borrar(ns: String, id: int) -> void:
	var e = _ns.get(ns, {}).get(id)
	if e != null:
		e.n.visible = false; _pool.get_or_add(e.tipo, []).append(e.n); _ns[ns].erase(id); _total -= 1
func _marco(frame: String, stamp = null) -> Transform3D:
	var t = tf.lookup_transform(fixed_frame, frame, stamp) if tf != null and frame != fixed_frame else null
	return t if t != null else Transform3D.IDENTITY

