## Superposición 2D de LINE_STRIP / LINE_LIST (Vita y vista Planta). Un comando por marcador (docs/31 H17).
var cam: Camera3D
var _lineas := {}            # clave → {mundo: PackedVector3Array, cols: PackedColorArray, ancho: float, tira: bool}
var _t := 0

func poner(clave: String, m, marco: Transform3D) -> void:
	var w := PackedVector3Array(); var c := PackedColorArray()
	var por_punto: bool = m.colors.size() == m.points.size()
	for i in m.points.size():
		var p = m.points[i]
		w.append(marco * rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
		var k = m.colors[i] if por_punto else m.color
		c.append(Color(k.r, k.g, k.b, k.a))
	_lineas[clave] = {"mundo": w, "cols": c, "ancho": m.scale.x, "tira": m.type == 4}
	queue_redraw()

func _process(_dt: float) -> void:
	if Time.get_ticks_msec() - _t >= 50:                 # ≤ 20 Hz de reproyección (docs/31 §3)
		_t = Time.get_ticks_msec(); queue_redraw()

func _draw() -> void:
	for e in _lineas.values():
		var px := PackedVector2Array(); var cs := PackedColorArray()
		for i in e.mundo.size():
			if cam.is_position_behind(e.mundo[i]):
				continue                                  # simplificación: se corta el tramo
			px.append(cam.unproject_position(e.mundo[i])); cs.append(e.cols[i])
		var ancho := maxf(1.0, e.ancho * 522.0 / maxf(0.1, cam.global_position.distance_to(e.mundo[0])))
		if e.tira and px.size() >= 2:
			draw_polyline_colors(px, cs, ancho)
		elif px.size() >= 2:
			draw_multiline_colors(px, cs, ancho)

## fabrica.gd — líneas como prismas triangulares (6 tri/segmento, docs/31 §2.2). PC: color por vértice.
static func lineas_3d(pts: PackedVector3Array, cols: PackedColorArray, ancho: float, tira: bool) -> ArrayMesh:
	var v := PackedVector3Array(); var c := PackedColorArray()
	var paso := 1 if tira else 2
	var r := ancho * 0.5
	var i := 0
	while i + 1 < pts.size():
		var a := pts[i]; var b := pts[i + 1]
		var d := (b - a).normalized()
		var u := d.cross(Vector3.UP if absf(d.y) < 0.99 else Vector3.RIGHT).normalized()
		var w := d.cross(u)
		var o := [u * r, (-u * 0.5 + w * 0.866) * r, (-u * 0.5 - w * 0.866) * r]
		for k in 3:
			var o0: Vector3 = o[k]; var o1: Vector3 = o[(k + 1) % 3]
			for q in [[a, o0, i], [b, o0, i + 1], [b, o1, i + 1], [a, o0, i], [b, o1, i + 1], [a, o1, i]]:
				v.append(q[0] + q[1]); c.append(cols[q[2]])
		i += paso
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = v; arr[Mesh.ARRAY_COLOR] = c
	var mesh := ArrayMesh.new()
	if v.size() > 0:
		mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	return mesh

static func material_vertices() -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.vertex_color_use_as_albedo = true
	m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	return m

