## CUBE_LIST / SPHERE_LIST en PC (points_marker.cpp:102-135): MultiMesh con color por instancia.
const Fab := preload("res://comun/viz/fabrica.gd")
func aplicar(m) -> bool:
	if multimesh == null:
		multimesh = MultiMesh.new()
		multimesh.transform_format = MultiMesh.TRANSFORM_3D
		multimesh.use_colors = true
	multimesh.mesh = Fab.malla(Fab.CUBO if m.type == 6 else Fab.ESFERA)
	material_override = Fab.material_vertices()        # cacheado; no tocar la malla compartida
	var pts: Array = m.points
	var por_punto: bool = m.colors.size() == pts.size()
	multimesh.instance_count = pts.size()
	var b := Basis.from_scale(Fab.escala(m.scale))
	for i in pts.size():
		var p = pts[i]
		multimesh.set_instance_transform(i, Transform3D(b, rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z))))
		var k = m.colors[i] if por_punto else m.color
		multimesh.set_instance_color(i, Color(k.r, k.g, k.b, k.a))
	return pts.size() > 0

## fabrica.gd — horneado Vita de SPHERE_LIST (octaedros) / CUBE_LIST con UV a la paleta (docs/31 §2.1).
static func hornear_lista(m, octaedro: bool) -> ArrayMesh:
	var v := PackedVector3Array(); var uv := PackedVector2Array()
	var e := escala(m.scale) * 0.5
	var por_punto: bool = m.colors.size() == m.points.size()
	var caras: Array = OCTA_CARAS if octaedro else CUBO_CARAS  # tablas constantes de vértices unidad (±1)
	for i in m.points.size():
		var p = m.points[i]
		var c := rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z))
		var k = m.colors[i] if por_punto else m.color
		var t := Paleta.uv(Color(k.r, k.g, k.b, k.a))          # centro del texel más cercano (16×16)
		for q in caras:
			v.append(c + q * e); uv.append(t)
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = v; arr[Mesh.ARRAY_TEX_UV] = uv
	var mesh := ArrayMesh.new()
	mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	mesh.surface_set_material(0, Paleta.material())           # albedo_texture = paleta con texel alfa 0 (H8)
	return mesh

const OCTA_CARAS := [Vector3(1,0,0), Vector3(0,1,0), Vector3(0,0,1), Vector3(0,0,1), Vector3(0,1,0), Vector3(-1,0,0),
	Vector3(-1,0,0), Vector3(0,1,0), Vector3(0,0,-1), Vector3(0,0,-1), Vector3(0,1,0), Vector3(1,0,0),
	Vector3(1,0,0), Vector3(0,0,1), Vector3(0,-1,0), Vector3(0,0,1), Vector3(-1,0,0), Vector3(0,-1,0),
	Vector3(-1,0,0), Vector3(0,0,-1), Vector3(0,-1,0), Vector3(0,0,-1), Vector3(1,0,0), Vector3(0,-1,0)]

