## POINTS en 2D (Vita): un lote, 2 triángulos por punto (docs/31 §2.3, H17).
var cam: Camera3D
var mundo := PackedVector3Array()
var cols := PackedColorArray()
var lado_m := 0.05
var _ci: RID

func _ready() -> void:
	_ci = get_canvas_item()

func _draw() -> void:
	var px := PackedVector2Array(); var cs := PackedColorArray(); var idx := PackedInt32Array()
	for i in mundo.size():
		if cam.is_position_behind(mundo[i]):
			continue
		var c := cam.unproject_position(mundo[i])
		var h := maxf(1.0, lado_m * 522.0 / maxf(0.1, cam.global_position.distance_to(mundo[i]))) * 0.5
		var b := px.size()
		px.append_array(PackedVector2Array([c + Vector2(-h, -h), c + Vector2(h, -h), c + Vector2(h, h), c + Vector2(-h, h)]))
		for k in 4:
			cs.append(cols[i])
		idx.append_array(PackedInt32Array([b, b + 1, b + 2, b, b + 2, b + 3]))
	if idx.size() > 0:
		RenderingServer.canvas_item_add_triangle_array(_ci, idx, px, cs)

## fabrica.gd — MESH_RESOURCE (mesh_resource_marker.cpp:95-155).
static var paquetes := {"turtlebot3_description": "res://robots/tb3/"}   # package:// → res:// (config)
static var _cache := {}

static func resolver(uri: String) -> String:
	if uri.begins_with("package://"):
		var resto := uri.trim_prefix("package://")
		var pkg := resto.get_slice("/", 0)
		if paquetes.has(pkg):
			return paquetes[pkg] + resto.trim_prefix(pkg + "/")
	return uri.trim_prefix("file://")

static func cargar_malla(uri: String) -> Node3D:
	if _cache.has(uri):
		var c = _cache[uri]
		return c.instantiate() if c is PackedScene else (c.duplicate() if c is Node else _envolver(c))
	var ruta := resolver(uri)
	var vita := OS.has_feature("vita")
	var base := ruta.get_basename()
	for ext in [".tscn", ".res", ".glb"]:              # horneado/pre-importado (en la Vita, la ÚNICA vía)
		if ResourceLoader.exists(base + ext):
			var r = load(base + ext)
			_cache[uri] = r
			return r.instantiate() if r is PackedScene else _envolver(r)
	if not vita and ruta.get_extension() in ["glb", "gltf"] and FileAccess.file_exists(ruta):
		var doc := GLTFDocument.new(); var st := GLTFState.new()
		if doc.append_from_file(ruta, st) == OK:
			var n := doc.generate_scene(st)
			_cache[uri] = n.duplicate()
			return n
	push_warning("MESH_RESOURCE no disponible: %s (se dibuja un cubo)" % uri)
	return _envolver(malla(CUBO))

static func _envolver(m: Mesh) -> Node3D:
	var mi := MeshInstance3D.new()
	mi.mesh = m
	return mi

## fabrica.gd — TRIANGLE_LIST (triangle_list_marker.cpp:100-125, :295-306).
static func malla_triangulos(m) -> ArrayMesh:
	var n: int = m.points.size()
	if n == 0 or n % 3 != 0:
		return null
	var por_vertice: bool = m.colors.size() == n
	var por_tri: bool = m.colors.size() == n / 3
	var vita := OS.has_feature("vita")
	var v := PackedVector3Array(); var c := PackedColorArray(); var uv := PackedVector2Array()
	for i in n:
		var p = m.points[i]
		v.append(rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
		var k = m.colors[i] if por_vertice else (m.colors[i / 3] if por_tri else m.color)
		var col := Color(k.r, k.g, k.b, k.a)
		if vita:
			uv.append(Paleta.uv(col if i % 3 == 0 else c[i - i % 3]))   # un color por triángulo
			c.append(col)
		else:
			c.append(col)
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = v
	if vita:
		arr[Mesh.ARRAY_TEX_UV] = uv
	else:
		arr[Mesh.ARRAY_COLOR] = c
	var mesh := ArrayMesh.new()
	mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	mesh.surface_set_material(0, Paleta.material() if vita else material_vertices())
	return mesh

## Cliente Vita de /vita/marcadores (formato propuesto en este post). Mismo gestor que el PC (ficha Marker).
const POR_MARCADOR := 10
var gestor                       # gestor de marcadores (ficha Marker)
var _seq := -1
var _vistos := {}                # clave → true del seq en curso
var _trozos := 0

func on_marcadores(m) -> void:
	var d: PackedFloat32Array = m.data
	if d.size() < 4:
		return
	var seq := int(d[0]); var n_trozos := int(d[2]); var n := int(d[3])
	if seq != _seq:
		_seq = seq; _vistos.clear(); _trozos = 0
	_trozos += 1
	for i in n:
		var b := 4 + i * POR_MARCADOR
		if b + POR_MARCADOR > d.size():
			break
		var clave := int(d[b])
		_vistos[clave] = true
		var col := int(d[b + 9])
		gestor.poner_compacto(clave, int(d[b + 1]),                          # tipo
			Transform3D(Basis(Vector3.UP, d[b + 5]), rclgd.ros_to_godot_vector(Vector3(d[b + 2], d[b + 3], d[b + 4]))),
			Vector3(d[b + 7], d[b + 8], d[b + 6]),                           # escala en ejes Godot (s.y, s.z, s.x)
			Paleta.color(col & 0xFF, ((col >> 8) & 0xF) / 15.0))
	if _trozos == n_trozos:
		gestor.retener_solo(_vistos)                 # estado completo: lo no visto se recicla (sin DELETE perdidos)

