## Cliente de marcadores interactivos (PC, rclgd). Protocolo de interactive_marker_server.cpp:70-91.
@export var ns := "/simple_marker"
var ctx
var gestor                                          # gestor de Marker (ficha Marker)
var _cli: RosClient; var _sub: RosSubscriber
var _seq := -1
var ims := {}                                       # nombre → InteractiveMarker (RosMsg)

func _ready() -> void:
	_cli = ctx.nodo.create_client(ns + "/get_interactive_markers", "visualization_msgs/srv/GetInteractiveMarkers")
	_sub = ctx.nodo.create_subscription(ns + "/update", "visualization_msgs/msg/InteractiveMarkerUpdate", _on_update, ctx.qos(false, 100))
	await _pedir_estado()

func _pedir_estado() -> void:
	var r = await _cli.async_send_request(_cli.create_request()).completed
	_seq = r.sequence_number
	ims.clear()
	for im in r.markers: _poner(im)

func _on_update(u) -> void:
	if _seq < 0 or u.seq_num < _seq:
		return
	if u.seq_num > _seq + (1 if u.type == 1 else 0):
		await _pedir_estado()                       # hueco (update o keep-alive adelantado): estado completo
		return
	_seq = u.seq_num
	for im in u.markers: _poner(im)
	for p in u.poses:
		if ims.has(p.name):
			ims[p.name].pose = p.pose
			gestor.mover_ns(p.name, Fab.pose(p.pose))   # mueve todos los markers del IM (ns = nombre)
	for nombre in u.erases: ims.erase(nombre); gestor.borrar_ns(nombre)

func _poner(im) -> void:
	ims[im.name] = im
	for c in im.controls:
		for mk in c.markers:
			mk.ns = im.name; mk.header = im.header   # el gestor los cuelga de la pose del IM
			gestor.on_marker(mk)

extends Node3D
## Arrastre MOVE_PLANE de un IM y publicación de feedback (PC ratón / Vita táctil frontal).
@export var ns := "/simple_marker"
@export var hz_feedback := 20.0
var ctx
var cam: Camera3D
var im_nombre := ""
var control := ""
var frame := "map"
var _pub: RosPublisher; var _plano: Plane
var _activo := false; var _t := 0

func _ready() -> void:
	_pub = ctx.nodo.create_publisher(ns + "/feedback", "visualization_msgs/msg/InteractiveMarkerFeedback", ctx.qos(true, 1))

func _unhandled_input(ev: InputEvent) -> void:
	var pulsado := (ev is InputEventMouseButton and ev.button_index == MOUSE_BUTTON_LEFT) or ev is InputEventScreenTouch
	if pulsado and ev.pressed and not _activo:
		_activo = true; _plano = Plane(global_basis.x, global_position)   # MOVE_PLANE: plano y-z ⇒ normal = eje x del control
		_enviar(4)                                                         # MOUSE_DOWN
	elif pulsado and not ev.pressed and _activo:
		_activo = false; _enviar(5)                                        # MOUSE_UP
	elif _activo and (ev is InputEventMouseMotion or ev is InputEventScreenDrag):
		var p = _plano.intersects_ray(cam.project_ray_origin(ev.position), cam.project_ray_normal(ev.position))
		if p != null:
			global_position = p
			if Time.get_ticks_msec() - _t >= int(1000.0 / hz_feedback):
				_t = Time.get_ticks_msec(); _enviar(1)                     # POSE_UPDATE

func _enviar(evento: int) -> void:
	var f := RosMsg.from_type("visualization_msgs/msg/InteractiveMarkerFeedback")
	f.header.frame_id = frame; f.header.stamp = ctx.nodo.now()
	f.client_id = "/vita" if OS.has_feature("vita") else "/godot"
	f.marker_name = im_nombre; f.control_name = control; f.event_type = evento
	var p := rclgd.godot_to_ros_vector(global_position)
	var q := rclgd.godot_to_ros_quat(global_basis.get_rotation_quaternion())
	f.pose.position.x = p.x; f.pose.position.y = p.y; f.pose.position.z = p.z
	f.pose.orientation.x = q.x; f.pose.orientation.y = q.y; f.pose.orientation.z = q.z; f.pose.orientation.w = q.w
	_pub.publish(f)

extends Control
