@export var ancho_imagen := 640.0
var _m := {}                                   # "ns/id" → [msg, expira_ms]

func on_image_marker(m) -> void:
	var k := "%s/%d" % [m.ns, m.id]
	if m.action == 1:
		_m.erase(k)
	else:
		var vida: float = m.lifetime.sec + m.lifetime.nanosec * 1e-9
		_m[k] = [m, Time.get_ticks_msec() + int(vida * 1000.0) if vida > 0.0 else -1]
	queue_redraw()

func _draw() -> void:
	var s := size.x / ancho_imagen
	var ahora := Time.get_ticks_msec()
	for k in _m.keys():
		var m = _m[k][0]
		if _m[k][1] >= 0 and ahora > _m[k][1]:
			_m.erase(k); continue
		var oc := Color(m.outline_color.r, m.outline_color.g, m.outline_color.b, m.outline_color.a)
		var fc := Color(m.fill_color.r, m.fill_color.g, m.fill_color.b, m.fill_color.a)
		var pts := PackedVector2Array()
		for p in m.points:
			pts.append(Vector2(p.x, p.y) * s)
		match m.type:
			0:
				var c := Vector2(m.position.x, m.position.y) * s
				if m.filled: draw_circle(c, m.scale * 0.5 * s, fc)
				draw_arc(c, m.scale * 0.5 * s, 0.0, TAU, 24, oc, 1.0)
			1:
				if pts.size() > 1: draw_polyline(pts, oc, 1.0)
			2:
				if pts.size() > 1: draw_multiline(pts, oc, 1.0)
			3:
				if m.filled and pts.size() > 2: draw_colored_polygon(pts, fc)
				if pts.size() > 1: draw_polyline(pts + PackedVector2Array([pts[0]]), oc, 1.0)
			4:
				for p in pts: draw_rect(Rect2(p - Vector2.ONE, Vector2(2, 2)), oc)

## fabrica.gd — shape_msgs/Mesh → ArrayMesh (PC indexada; la Vita la aplana sola al subirla, H3).
static func malla_shape(msh) -> ArrayMesh:
	var v := PackedVector3Array()
	for p in msh.vertices:
		v.append(rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
	var idx := PackedInt32Array()
	for t in msh.triangles:
		var vi = t.vertex_indices
		# Godot usa sentido horario como cara frontal; ROS no fija sentido: invertir 1-2 si se ve por dentro.
		idx.append_array([int(vi[0]), int(vi[2]), int(vi[1])])
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for i in idx:
		st.add_vertex(v[i])
	st.index()
	st.generate_normals()
	return st.commit()

## fabrica.gd — shape_msgs/Plane → transform de un PlaneMesh (normal +Y de Godot).
static func plano(pl, lado := 4.0) -> MeshInstance3D:
	var c: PackedFloat64Array = pl.coef
	var n_ros := Vector3(c[0], c[1], c[2])
	var l2 := n_ros.length_squared()
	if l2 < 1e-12:
		return null
	var punto := rclgd.ros_to_godot_vector(-c[3] * n_ros / l2)
	var n := rclgd.ros_to_godot_vector(n_ros).normalized()
	var x := n.cross(Vector3.FORWARD if absf(n.z) < 0.99 else Vector3.RIGHT).normalized()
	var mi := MeshInstance3D.new()
	var pm := PlaneMesh.new()
	pm.size = Vector2(lado, lado)
	mi.mesh = pm
	mi.transform = Transform3D(Basis(x, n, x.cross(n)), punto)
	var mat := StandardMaterial3D.new()
	mat.albedo_color = Color(0.2, 0.6, 1.0, 0.35)
	mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	mat.cull_mode = BaseMaterial3D.CULL_DISABLED
	mi.material_override = mat
	return mi
